async function sendSitemap(method, res, callback) {
	if (meta.config['feeds:disableSitemap']) {
		return setImmediate(callback);
	}
	const xml = await method();
	if (!xml) {
		return callback();
	}
	res.header('Content-Type', 'application/xml');
	res.send(xml);
}

